// WP-8.1 froxel fog on Vulkan: see include/fuse/renderer/volumetric/gpu/froxel_fog.hpp.
#include <fuse/renderer/volumetric/gpu/froxel_fog.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>
#include <initializer_list>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp81.cmake from shaders/volumetric/*: kFog<Kernel><Slang|Glsl>Spv and
// FUSE_FOG_GPU_{SLANG,GLSL} when every kernel of a language exists.
#include "froxel_fog_spv.h"
#endif

namespace fuse::renderer::volumetric_gpu {

namespace {
constexpr u32 kPushBytes = sizeof(FogPush);
constexpr u32 kFrameStride = 1536u; ///< ring slot size (>= sizeof(FogFrameConstants), 256-aligned)
static_assert(sizeof(FogFrameConstants) <= kFrameStride, "frame ring slot");
constexpr u32 kOutputFormat = static_cast<u32>(GpuFormat::R16G16B16A16Sfloat);
constexpr u64 kTexel = 16u; ///< f32x4

BufferUsage bufferUsage(std::initializer_list<BufferUsage> bits) {
    u32 u = 0;
    for (const BufferUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<BufferUsage>(u);
}

ImageUsage imageUsage(std::initializer_list<ImageUsage> bits) {
    u32 u = 0;
    for (const ImageUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<ImageUsage>(u);
}

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

FogBufferLayout FogBufferLayout::compute(u32 froxelCount) {
    FogBufferLayout l{};
    u64 cursor = 0;
    auto take = [&](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + std::max<u64>(bytes, 16u));
        return at;
    };
    const u64 n = froxelCount;
    l.current = take(n * kTexel);
    l.history[0] = take(n * kTexel);
    l.history[1] = take(n * kTexel);
    l.integrated = take(n * kTexel);
    l.workBytes = cursor;
    return l;
}

FogCapabilities queryFogCapabilities(const VulkanDevice* device) {
    FogCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    VkFormatProperties props{};
    vkGetPhysicalDeviceFormatProperties(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()),
                                        static_cast<VkFormat>(kOutputFormat), &props);
    if ((props.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT) == 0u) {
        c.reason = "RGBA16F storage images unsupported";
        return c;
    }
    c.fog = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

FroxelFog::~FroxelFog() { destroy(); }

bool FroxelFog::init(const FroxelFogDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u) {
        return false;
    }
    if (!queryFogCapabilities(desc.device).fog) {
        return false;
    }
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "froxel_fog.frame";
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr ||
        m_frameRing.deviceAddress == 0u || !createPipelines()) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void FroxelFog::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    Retired current{};
    current.buffer = m_work;
    current.image = m_output.image;
    current.slots[0] = m_output.slot;
    for (u32 i = 0; i < kInputCount; ++i) {
        current.slots[1u + i] = m_inputSlots[i];
    }
    destroyRetired(current);
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_work = Buffer{};
    m_workQueue = rg::kNoQueue;
    m_output = Output{};
    m_frameRing = Buffer{};
    m_frameAddress = 0;
    m_retired.clear();
    for (u32 i = 0; i < kInputCount; ++i) {
        m_inputImages[i] = nullptr;
        m_inputSlots[i] = BindlessSlotHandle{};
        m_inputHandles[i] = 0u;
    }
    m_froxels = 0;
    m_width = m_height = 0;
    m_layout = FogBufferLayout{};
    m_recordCount = 0;
    m_language = "none";
    m_stats = FogStats{};
    m_constants = FogFrameConstants{};
    m_hasDump = false;
    m_apply = false;
    m_historyIndex = 0;
    m_historyValid = false;
    m_frameIndex = 0;
    m_initialized = false;
}

bool FroxelFog::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_FOG_GPU_SLANG)
    if (m_desc.language == FogKernelLanguage::Auto || m_desc.language == FogKernelLanguage::Slang) {
        k[kInject] = code(kFogInjectSlangSpv);
        k[kTemporal] = code(kFogTemporalSlangSpv);
        k[kIntegrate] = code(kFogIntegrateSlangSpv);
        k[kApply] = code(kFogApplySlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_FOG_GPU_GLSL)
    if (!found && (m_desc.language == FogKernelLanguage::Auto || m_desc.language == FogKernelLanguage::Glsl)) {
        k[kInject] = code(kFogInjectGlslSpv);
        k[kTemporal] = code(kFogTemporalGlslSpv);
        k[kIntegrate] = code(kFogIntegrateGlslSpv);
        k[kApply] = code(kFogApplyGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    return false;
#endif
}

bool FroxelFog::createWork(u32 froxelCount) {
    const FogBufferLayout layout = FogBufferLayout::compute(froxelCount);
    BufferDesc work{};
    work.size = static_cast<usize>(layout.workBytes);
    work.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    work.memoryUsage = MemoryUsage::GpuOnly;
    work.name = "froxel_fog.work";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(work, fresh) || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_work.handle != nullptr) {
        Retired old{};
        old.buffer = m_work;
        retire(old);
    }
    m_work = fresh;
    m_workQueue = rg::kNoQueue;
    m_layout = layout;
    m_froxels = froxelCount;
    ++m_stats.workRebuilds;
    return true;
}

bool FroxelFog::createOutput(u32 width, u32 height) {
    Output o{};
    TextureDesc d{};
    d.width = width;
    d.height = height;
    d.format = static_cast<GpuFormat>(kOutputFormat);
    d.usage = imageUsage({ImageUsage::Storage, ImageUsage::Sampled, ImageUsage::TransferSrc});
    d.name = "froxel_fog.output";
    if (!m_desc.allocator->createImage(d, o.image)) {
        return false;
    }
    o.slot = m_desc.bindless->registerTextureSlot(o.image, true);
    if (!o.slot.isValid()) {
        m_desc.allocator->destroyImage(o.image);
        return false;
    }
    if (m_output.image.image != nullptr) {
        Retired old{};
        old.image = m_output.image;
        old.slots[0] = m_output.slot;
        retire(old);
    }
    m_output = o;
    m_width = width;
    m_height = height;
    ++m_stats.outputRebuilds;
    return true;
}

bool FroxelFog::bindInput(u32 index, const Texture* image) {
    void* handle = image != nullptr ? image->image : nullptr;
    if (handle == m_inputImages[index] && (handle == nullptr || m_inputSlots[index].isValid())) {
        return true;
    }
    if (m_inputSlots[index].isValid()) {
        Retired old{};
        old.slots[1u + index] = m_inputSlots[index];
        retire(old);
    }
    m_inputSlots[index] = BindlessSlotHandle{};
    m_inputImages[index] = nullptr;
    m_inputHandles[index] = 0u;
    if (handle == nullptr) {
        return true;
    }
    m_inputSlots[index] = m_desc.bindless->registerTextureSlot(*image, false);
    if (!m_inputSlots[index].isValid()) {
        return false;
    }
    m_inputImages[index] = handle;
    m_inputHandles[index] = m_desc.bindless->shaderHandle(m_inputSlots[index]);
    ++m_stats.inputBinds;
    return true;
}

void FroxelFog::retire(Retired r) {
    r.serial = m_frameSerial;
    m_retired.push_back(r);
    ++m_stats.retired;
}

void FroxelFog::destroyRetired(Retired& r) {
    for (BindlessSlotHandle& slot : r.slots) {
        if (slot.isValid()) {
            m_desc.bindless->unregisterSlot(slot);
        }
    }
    if (r.buffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(r.buffer);
    }
    if (r.image.image != nullptr) {
        m_desc.allocator->destroyImage(r.image);
    }
    r = Retired{};
}

u32 FroxelFog::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyRetired(m_retired[i]);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

bool FroxelFog::beginFrame(u64 frameSerial, const FroxelFogSettings& settings, const FogFrameDesc& frame) {
    if (!m_initialized) {
        return false;
    }
    const bool apply = frame.depth != nullptr || frame.lit != nullptr;
    u32 w = 0;
    u32 h = 0;
    if (apply) {
        if (frame.depth == nullptr || frame.lit == nullptr || frame.depth->image == nullptr || frame.lit->image == nullptr) {
            return false;
        }
        w = frame.depth->desc.width;
        h = frame.depth->desc.height;
        if (w == 0u || h == 0u || frame.lit->desc.width != w || frame.lit->desc.height != h) {
            return false;
        }
    }
    FogFrameConstants c{};
    if (!resolveFogConstants(settings, frame.camera, &m_prevCamera, true, m_frameIndex, w, h, c)) {
        return false;
    }
    // History: same grid and range as last frame's (the slice table), not reset.
    const bool sameGrid = m_prevGrid[0] == c.gridX && m_prevGrid[1] == c.gridY && m_prevGrid[2] == c.gridZ &&
                          m_prevRange[0] == c.nearPlane && m_prevRange[1] == c.farPlane;
    if (!m_historyValid || frame.resetHistory || !sameGrid || c.froxelCount != m_froxels) {
        c.flags &= ~static_cast<u32>(kFogFlagHistory | kFogFlagReproject);
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    m_stats.applied = false;
    if (c.froxelCount != m_froxels || m_work.handle == nullptr) {
        if (!createWork(c.froxelCount)) {
            m_historyValid = false;
            return false;
        }
        c.flags &= ~static_cast<u32>(kFogFlagHistory | kFogFlagReproject);
    }
    if (apply && (w != m_width || h != m_height || m_output.image.image == nullptr)) {
        if (!createOutput(w, h)) {
            return false;
        }
    }
    if (!bindInput(0, apply ? frame.depth : nullptr) || !bindInput(1, apply ? frame.lit : nullptr)) {
        return false;
    }
    m_apply = apply;
    const u64 work = m_work.deviceAddress;
    c.current = work + m_layout.current;
    c.historyPrev = work + m_layout.history[m_historyIndex];
    c.historyCur = work + m_layout.history[m_historyIndex ^ 1u];
    c.integrated = work + m_layout.integrated;
    c.dump = apply ? frame.dumpAddress : 0u;
    c.lighting = frame.lighting;
    if (frame.lighting != 0u) {
        c.flags |= kFogFlagLights;
    }
    c.shadows = settings.medium.receive_shadows ? frame.shadows : 0u;
    if (c.shadows != 0u) {
        c.flags |= kFogFlagShadows;
    }
    c.inputDepth = m_inputHandles[0];
    c.inputLit = m_inputHandles[1];
    c.output = apply ? m_desc.bindless->shaderHandle(m_output.slot) : 0u;
    m_hasDump = c.dump != 0u;
    m_stats.historyUsed = (c.flags & kFogFlagHistory) != 0u;
    m_constants = c;
    const u32 slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    const u64 offset = static_cast<u64>(slot) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &c, sizeof(c));
    m_frameAddress = m_frameRing.deviceAddress + offset;

    // This frame's temporal output becomes the next frame's history.
    m_historyIndex ^= 1u;
    m_historyValid = true;
    m_prevCamera = frame.camera;
    m_prevGrid[0] = c.gridX;
    m_prevGrid[1] = c.gridY;
    m_prevGrid[2] = c.gridZ;
    m_prevRange[0] = c.nearPlane;
    m_prevRange[1] = c.farPlane;
    ++m_frameIndex;
    return true;
}

FogGraphRefs FroxelFog::importInto(rg::Graph& graph) {
    FogGraphRefs refs{};
    if (!m_initialized || m_work.handle == nullptr) {
        return refs;
    }
    refs.work = graph.importBuffer(
        rg::ImportedBuffer{m_work.handle, m_work.desc.size, m_workQueue, &m_workQueue, "froxel_fog.work"});
    if (m_apply && m_output.image.image != nullptr) {
        rg::ImportedImage i{};
        i.image = m_output.image.image;
        i.view = m_output.image.view;
        i.format = kOutputFormat;
        i.width = m_width;
        i.height = m_height;
        i.initialLayout = m_output.layout;
        i.initialQueue = m_output.queue;
        i.layoutTracker = &m_output.layout;
        i.queueTracker = &m_output.queue;
        i.name = "froxel_fog.output";
        refs.output = graph.importImage(i);
    }
    return refs;
}

FroxelFog::PassRecord* FroxelFog::nextRecord(u32 kernel) {
    if (m_recordCount >= kMaxPasses) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->kernel = kernel;
    r->push.frame = m_frameAddress;
    return r;
}

void FroxelFog::addPasses(rg::Graph& graph, const FogGraphRefs& refs, const FogGraphInputs& inputs) {
    if (!m_initialized || !refs.work.valid()) {
        return;
    }
    const FogFrameConstants& c = m_constants;
    if (PassRecord* r = nextRecord(kInject)) {
        r->groups[0] = groups(c.froxelCount, kFogLinearGroup);
        ++m_stats.passes;
        rg::PassBuilder inject = graph.addPass("fog.inject", &FroxelFog::recordDispatch, r);
        inject.use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
        if ((c.flags & kFogFlagLights) != 0u) {
            if (inputs.lights.valid()) {
                inject.use(inputs.lights, rg::Access::StorageRead, {}, rg::kStageCompute);
            }
            if (inputs.scene != nullptr) {
                gpu_scene::GpuScene::useAll(inject, *inputs.scene, rg::Access::StorageRead, rg::kStageCompute);
            }
        }
    }
    if (PassRecord* r = nextRecord(kTemporal)) {
        r->groups[0] = groups(c.froxelCount, kFogLinearGroup);
        ++m_stats.passes;
        graph.addPass("fog.temporal", &FroxelFog::recordDispatch, r)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    if (PassRecord* r = nextRecord(kIntegrate)) {
        r->groups[0] = groups(c.gridX * c.gridY, kFogLinearGroup);
        ++m_stats.passes;
        graph.addPass("fog.integrate", &FroxelFog::recordDispatch, r)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    if (m_apply && refs.output.valid() && inputs.depth.valid() && inputs.lit.valid()) {
        if (PassRecord* r = nextRecord(kApply)) {
            r->groups[0] = groups(m_width, kFogTile);
            r->groups[1] = groups(m_height, kFogTile);
            ++m_stats.passes;
            m_stats.applied = true;
            rg::PassBuilder applyPass = graph.addPass("fog.apply", &FroxelFog::recordDispatch, r);
            applyPass.use(inputs.depth, rg::Access::SampledRead, {}, rg::kStageCompute)
                .use(inputs.lit, rg::Access::SampledRead, {}, rg::kStageCompute)
                .use(refs.work, rg::Access::StorageRead, {}, rg::kStageCompute)
                .use(refs.output, rg::Access::StorageWrite, {}, rg::kStageCompute);
            if (m_hasDump && inputs.dump.valid()) {
                applyPass.use(inputs.dump, rg::Access::StorageWrite,
                              rg::BufferRange{0, static_cast<u64>(m_width) * m_height * kTexel}, rg::kStageCompute);
            }
        }
    }
}

void FroxelFog::addCopy(rg::Graph& graph, const FogGraphRefs& refs, FogCopySource what, rg::BufferRef dst, u64 dstOffset) {
    if (!m_initialized || !dst.valid() || !refs.work.valid()) {
        return;
    }
    PassRecord* r = nextRecord(kKernelCount);
    if (r == nullptr) {
        return;
    }
    u64 src = 0;
    switch (what) {
    case FogCopySource::Current: src = m_layout.current; break;
    case FogCopySource::History: src = m_constants.historyCur - m_work.deviceAddress; break;
    case FogCopySource::HistoryPrev: src = m_constants.historyPrev - m_work.deviceAddress; break;
    case FogCopySource::Integrated: src = m_layout.integrated; break;
    }
    r->copySrc = src;
    r->copyBytes = copyBytes();
    r->copyDst = dstOffset;
    r->copyFrom = refs.work;
    r->copyTo = dst;
    ++m_stats.passes;
    graph.addPass("fog.copy", &FroxelFog::recordCopy, r)
        .use(refs.work, rg::Access::TransferSrc, rg::BufferRange{r->copySrc, r->copyBytes})
        .use(dst, rg::Access::TransferDst, rg::BufferRange{dstOffset, r->copyBytes});
}

void FroxelFog::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const FroxelFog& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       kPushBytes, &r.push);
    vkCmdDispatch(cmd, r.groups[0], r.groups[1], r.groups[2]);
#else
    (void)context;
    (void)user;
#endif
}

void FroxelFog::recordCopy(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const VkBufferCopy region{r.copySrc, r.copyDst, r.copyBytes};
    vkCmdCopyBuffer(cmd, static_cast<VkBuffer>(context.buffer(r.copyFrom)), static_cast<VkBuffer>(context.buffer(r.copyTo)),
                    1, &region);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::volumetric_gpu
